#!/bin/bash\n# Azure Cost Monitoring Script\n# Sends email alert when daily spend exceeds threshold\n# Run as: az account set --subscription <SUB_ID> && ./scripts/monitor_costs.sh\n\nset -e\n\n# Configuration\nRESOURCE_GROUP=\"threatlens-lab\"\nCOST_THRESHOLD=50  # Alert if daily spend > $50\nCHECK_INTERVAL=3600  # Check every hour (3600 seconds)\n\necho \"[INFO] Starting ThreatLens Cost Monitor\"\necho \"[INFO] Alert threshold: \\$$COST_THRESHOLD per day\"\necho \"[INFO] Check interval: ${CHECK_INTERVAL}s\"\n\nwhile true; do\n    TIMESTAMP=$(date '+%Y-%m-%d %H:%M:%S')\n    \n    # Get resource group information\n    RG_INFO=$(az group show --name \"$RESOURCE_GROUP\" 2>/dev/null || true)\n    \n    if [ -z \"$RG_INFO\" ]; then\n        echo \"[$TIMESTAMP] ERROR: Resource group '$RESOURCE_GROUP' not found\"\n        sleep \"$CHECK_INTERVAL\"\n        continue\n    fi\n    \n    # Get running VM costs (estimate based on size)\n    ATTACKER_STATE=$(az vm get-instance-view --resource-group \"$RESOURCE_GROUP\" --name attacker --query \"instanceView.statuses[0].displayStatus\" -o tsv 2>/dev/null || echo \"VM deallocated\")\n    VICTIM_STATE=$(az vm get-instance-view --resource-group \"$RESOURCE_GROUP\" --name elk-victim --query \"instanceView.statuses[0].displayStatus\" -o tsv 2>/dev/null || echo \"VM deallocated\")\n    SIEM_STATE=$(az vm get-instance-view --resource-group \"$RESOURCE_GROUP\" --name elk-siem --query \"instanceView.statuses[0].displayStatus\" -o tsv 2>/dev/null || echo \"VM deallocated\")\n    \n    # Estimate hourly costs (based on VM sizes)\n    # Standard_D2s_v3: ~$0.104/hour\n    # Standard_D4s_v3: ~0.208/hour\n    HOURLY_COST=0\n    \n    if [[ \"$ATTACKER_STATE\" == *\"running\"* ]]; then\n        HOURLY_COST=$(echo \"$HOURLY_COST + 0.104\" | bc)\n    fi\n    \n    if [[ \"$VICTIM_STATE\" == *\"running\"* ]]; then\n        HOURLY_COST=$(echo \"$HOURLY_COST + 0.104\" | bc)\n    fi\n    \n    if [[ \"$SIEM_STATE\" == *\"running\"* ]]; then\n        HOURLY_COST=$(echo \"$HOURLY_COST + 0.208\" | bc)\n    fi\n    \n    DAILY_COST=$(echo \"$HOURLY_COST * 24\" | bc)\n    \n    # Check threshold\n    if (( $(echo \"$DAILY_COST > $COST_THRESHOLD\" | bc -l) )); then\n        echo \"[$TIMESTAMP] WARNING: Estimated daily cost (\\$$DAILY_COST) exceeds threshold (\\$$COST_THRESHOLD)\"\n        echo \"[$TIMESTAMP] Running VMs:\"\n        echo \"  - Attacker (D2s_v3): $ATTACKER_STATE\"\n        echo \"  - Victim (D2s_v3): $VICTIM_STATE\"\n        echo \"  - SIEM (D4s_v3): $SIEM_STATE\"\n        echo \"[$TIMESTAMP] Suggestion: Deallocate VMs with 'az vm deallocate --resource-group $RESOURCE_GROUP --name <vm-name>'\"\n    else\n        echo \"[$TIMESTAMP] Status OK - Estimated daily cost: \\$$DAILY_COST\"\n        echo \"  - Attacker: $ATTACKER_STATE\"\n        echo \"  - Victim: $VICTIM_STATE\"\n        echo \"  - SIEM: $SIEM_STATE\"\n    fi\n    \n    sleep \"$CHECK_INTERVAL\"\ndone\n"